export {journeyNext} from './journey.mjs';
export const journeySteps=[['定位','Locate'],['建筑','Building'],['楼层','Floor'],['门口','Door'],['确认','Confirm']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes={pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',building:'<path d="M3 21h18M5 21V6l7-3 7 3v15M9 21v-6h6v6M8 9h1m6 0h1m-8 3h1m6 0h1"/>',floor:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',door:'<path d="M4 21V3h16v18M8 21V7h9v14M13 14h1M2 21h20"/>',check:'<path d="m5 12 5 5L20 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',stairs:'<path d="M3 21h5v-5h5v-5h5V6h4M4 10V3h7M4 3l7 7"/>',lift:'<rect x="3" y="2" width="18" height="20" rx="2"/><path d="M8 12h8v10M12 12v10M7 7l2-2 2 2m2-2 2 2 2-2"/>',sign:'<path d="M12 3v18M3 5h15l3 4-3 4H3V5Zm3 4h10m-3-2 3 2-3 2"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3V9Zm4 12h4"/>',retry:'<path d="M4 9a8 8 0 1 1 0 7M4 3v6h6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3h.1"/>',toilet:'<circle cx="7" cy="4" r="2"/><circle cx="17" cy="4" r="2"/><path d="M4 9h6l1 6H3l1-6Zm1 6v6m4-6v6m6-12h4v7h-4V9Zm1 7v5m2-5v5"/>'};
export const journeyIcon=kind=>`<svg class="way-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[kind]||shapes.pin}</svg>`;
function artwork(stage,{p,b,en,stepFree}){
 const t=(zh,eng)=>en?eng:zh,code=p.type==='toilet'?t('厕所','TOILETS'):p.name.split('·').at(-1).trim(),f=p.floor??'?',i=(kind,x,y,size=24)=>`<svg x="${x}" y="${y}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${shapes[kind]}</svg>`;
 const label=[t('蓝色起点沿红线连接目标建筑。起点和连线为演示。','A blue origin is connected to the destination building by a red thread. Origin and connection are simulated.'),t('核对目标建筑名称牌，再进入入口。入口示意未经现场核验。','Match the building name sign, then enter. This entrance sketch is not field-verified.'),t('在楼层示意中核对目标楼层。楼层数量和位置为演示。','Match the highlighted destination floor in the illustrative stack. Floor count and positions are simulated.'),t('室内示例：从电梯或楼梯出口直行，转角向右，核对门牌。非真实室内路径。','Indoor example: from the lift or stairs, go ahead, turn right at the sign and match the door code. Not a real indoor route.'),t('由使用者核对建筑、楼层和门牌；系统不会仅凭位置判定找到。','The user matches building, floor and door sign. Location alone never marks the place as found.')][stage];
 let drawing='';
 if(stage===0)drawing=`<path class="way-street" d="M0 55h350M0 135h350M70 0v185M250 0v185"/><rect class="way-block" x="17" y="15" width="36" height="23" rx="3"/><rect class="way-block" x="95" y="12" width="125" height="26" rx="3"/><rect class="way-block" x="93" y="150" width="126" height="24" rx="3"/><path class="way-thread" d="M70 119H175V71H270"/><circle class="way-origin-halo" cx="70" cy="119" r="19"/><circle class="way-origin" cx="70" cy="119" r="7"/>${i('building',248,45,44)}<circle class="way-target" cx="270" cy="70" r="32"/><text x="70" y="160" text-anchor="middle">${t('起点','START')}</text><text x="270" y="125" class="way-code" text-anchor="middle">${esc(b.id)}</text>`;
 if(stage===1)drawing=`<path class="way-building" d="M64 158V40l111-25 111 25v118Z"/><path class="way-window" d="M87 63h25v21H87Zm49 0h25v21h-25Zm52 0h25v21h-25Zm48 0h25v21h-25Z"/><path class="way-door" d="M148 158v-46h54v46"/><rect class="way-sign" x="126" y="25" width="98" height="31" rx="3"/><text x="175" y="47" class="way-code" text-anchor="middle">${esc(b.id)}</text><path class="way-thread" d="M175 181v-56"/><path class="way-chevron" d="m165 135 10-11 10 11"/><text x="61" y="177">${t('核对楼名牌','NAME SIGN')}</text><path class="way-callout" d="M112 167 143 151"/>`;
 if(stage===2){const levels=['G','UG','1','2','3','4'];if(!levels.includes(f))levels.push(f);drawing=levels.map((level,index)=>{const y=155-index*24;return `<g class="${level===f?'way-level-target':'way-level'}"><path d="m90 ${y} 100-15 77 15-99 17Z"/><text x="290" y="${y+5}" class="way-floor-number">${esc(level)}</text>${level===f?`<circle cx="68" cy="${y}" r="5"/><path class="way-callout" d="M70 ${y}H95"/>`:''}</g>`;}).join('')+i(stepFree?'lift':'stairs',18,72,32)+`<text x="34" y="130" text-anchor="middle">${stepFree?t('电梯','LIFT'):t('楼梯','STAIRS')}</text>`;}
 if(stage===3)drawing=`<path class="way-room" d="M90 20h72v56H90ZM180 20h72v56h-72ZM90 118h72v50H90ZM180 118h72v50h-72Z"/><path class="way-corridor" d="M58 168V98H292"/><path class="way-thread" d="M58 155V98H292"/><circle class="way-origin" cx="58" cy="155" r="6"/>${i(stepFree?'lift':'stairs',13,129,27)}<circle class="way-turn" cx="232" cy="98" r="14"/><path class="way-chevron" d="M226 99h12m-5-5 5 5-5 5"/><rect class="way-sign" x="256" y="74" width="80" height="49" rx="3"/><text x="296" y="105" class="way-code" text-anchor="middle" style="font-size:${code.length>6?11:18}px">${esc(code.length>12?code.slice(-12):code)}</text><text x="160" y="105" text-anchor="middle" class="way-on-path">→</text><text x="239" y="145" text-anchor="middle">${t('转角指示牌','DIRECTION SIGN')}</text>`;
 if(stage===4)drawing=`<path class="way-building" d="M109 175V14h130v161"/><path class="way-door" d="M127 175V35h94v140"/><rect class="way-sign" x="136" y="55" width="76" height="38" rx="3"/><text x="174" y="80" text-anchor="middle" class="way-code" style="font-size:${code.length>6?11:18}px">${esc(code.length>12?code.slice(-12):code)}</text><circle cx="207" cy="124" r="3" fill="currentColor"/><circle class="way-confirm-seal" cx="245" cy="140" r="26"/>${i('help',229,124,32)}${p.type==='toilet'?i('toilet',150,103,44):''}`;
 return `<figure class="way-art" data-visual-step="${stage}"><svg viewBox="0 0 350 190" role="img" aria-label="${esc(label)}">${drawing}</svg><figcaption>${t('示意图 · 非实际路线','SCENARIO SKETCH · NOT A REAL ROUTE')}</figcaption></figure>`;
}
export function journeyMarkup({p,b,stage,en,origin,floor,stepFree,recovery,reminders,muted,estimate}){
 const t=(zh,eng)=>en?eng:zh,n=o=>en?o.name:o.zh,ico=journeyIcon,button=(id,zh,eng,kind='arrow',cls='primary full')=>`<button id="${id}" class="${cls}">${ico(kind)}<span>${t(zh,eng)}</span></button>`,sign=p.type==='toilet'?t('厕所','Toilets'):p.name.split('·').at(-1).trim(),f=p.floor??'?';
 const chip=(kind,value,caption)=>`<div class="way-fact">${ico(kind)}<span><small>${caption}</small><strong>${esc(value)}</strong></span></div>`;
 const headings=[t('从这里出发','Start here'),t('找到这栋楼','Find this building'),t('找到这一层','Find this floor'),t('认准这个门牌','Match this sign'),t('是这个地方吗？','The right place?')];
 const help=[t('核对蓝色起点。定位不符时可更换参考位置。本演示不会读取设备 GPS。','Check the blue origin pin. Change the reference location if needed. This demo does not read device GPS.'),t('按校园地图查找目标建筑，核对入口处的建筑名称牌，再确认进入大厅。','Find the building on the campus map, match its entrance name sign, then confirm entry to the foyer.'),t('查找楼层索引及电梯或楼梯标识，到层后核对出口楼层牌。同层目的地无需上下楼。','Use the floor directory and lift or stairs signs. Check the floor label at the exit. Stay on the entry floor if it matches.'),t('示例路线从本层出口进入走廊，直行后在转角向右，再核对门牌或设施标识。此示意不代表实际建筑布局。','The illustrative route follows a corridor from the floor exit, turns right at a sign, then matches the door or facility symbol. This is not the actual building layout.'),p.type==='toilet'?t('确认找到对应厕所，并核对所需设施可以使用。','Confirm this is the correct toilet and that the facilities needed are usable.'):t('核对课程中的教室信息与门口标识。位置变化不会自动完成任务。','Match the classroom in the class information to the door sign. A location update cannot complete the task.')][stage];
 let body=artwork(stage,{p,b,en,stepFree});
 if(stage===0)body+=chip('pin',n(origin),t('演示起点','SCENARIO ORIGIN'))+`<div class="way-utility">${button('locateScenario','重新定位','Locate again','pin','outline')}${button('changeJourneyOrigin','更换起点','Change origin','retry','text-button')}</div><label class="reminder-choice way-toggle"><input id="journeyReminder" type="checkbox" ${reminders?'checked':''}>${ico('bell')}<span>${t('到楼提醒 · 演示','Approach prompt · demo')}</span></label>`+button('confirmOrigin','起点正确，出发','Start here');
 if(stage===1)body+=`<div class="way-facts">${chip('building',n(b),t('核对楼名','MATCH THE BUILDING'))}${chip('pin',estimate,t('演示预计','SCENARIO ESTIMATE'))}</div>`+button('enterBuilding','已进入建筑','Inside the building','building')+`<div class="way-utility">${button('replayPrompt','到楼提示','Approach prompt','bell','text-button')}${button('muteGuide',muted?'恢复提醒':'暂停提醒',muted?'Resume':'Pause',muted?'bell':'check','text-button')}</div>`;
 if(stage===2)body+=`<div class="way-floor-target"><span>${ico('floor')}${t('目标楼层','DESTINATION FLOOR')}</span><strong>${esc(f)}</strong><small>${esc(floor)}</small></div><label class="step-free-choice way-toggle"><input id="stepFree" type="checkbox" ${stepFree?'checked':''}>${ico('lift')}<span>${t('优先电梯 · 演示','Prefer lift · demo')}</span></label>`+button('atFloor','楼层已核对','Floor matches','check');
 if(stage===3)body+=`<div class="way-sign-match"><span>${ico('sign')}<small>${t('寻找这个标识','LOOK FOR THIS SIGN')}</small></span><strong>↱ ${esc(sign)}</strong></div><div class="way-mini-trail" aria-label="${esc(help)}"><span>${ico(stepFree?'lift':'stairs')}${stepFree?t('电梯口','Lift exit'):t('楼梯口','Stairs exit')}</span><b aria-hidden="true">↑</b><span>${ico('sign')}${t('右转','Turn right')}</span><b aria-hidden="true">→</b><span>${ico(p.type==='toilet'?'toilet':'door')}${t('门牌','Door sign')}</span></div>`+button('showIndoorClue','放大室内图','Open indoor sketch','floor','outline full')+button('atDoor','门牌一致','Door sign matches','door');
 if(stage===4)body+=`<div class="way-match-list">${chip('building',b.id,t('建筑','BUILDING'))}${chip('floor',f,t('楼层','FLOOR'))}${chip(p.type==='toilet'?'toilet':'door',sign,t('门牌','SIGN'))}</div><p class="way-confirm-question">${p.type==='toilet'?t('地点正确，设施可用？','Correct place, facilities usable?'):t('门牌与课程地点一致？','Does the sign match the class?')}</p>`+button('finishGuide','找到了','Found it','check')+button('notFound','还没找到／无法使用','Not found / cannot use','help','outline full')+(recovery?`<section class="recovery-panel way-recovery" role="status"><h4>${ico('help')}${t('换一条线索','Try another clue')}</h4><div class="way-recovery-grid">${button('retryIndoor','重看门口','Door clue','door','outline')}${button('recheckFloor','核对楼层','Floor clue','floor','outline')}${p.type==='toilet'?button('otherToilets','其他厕所','Other toilets','toilet','outline'):''}${button('leaveFeedback','报告问题','Report a clue','sign','outline')}</div><p>${t('标识不符或通道受阻 → 咨询现场工作人员。','Missing signs or blocked access → ask on-site staff.')}</p></section>`:'');
 return `<div class="visual-journey"><div class="detail-toolbar"><span class="eyebrow">FOLLOW THE THREAD</span>${button('endGuide','退出','Exit','retry','text-button')}</div><div class="way-destination"><span>${ico(p.type==='toilet'?'toilet':'door')}<strong>${esc(n(p))}</strong></span><small>${esc(n(b))} · ${esc(floor)}</small></div><ol class="journey-progress" aria-label="${t('找路进度','Wayfinding progress')}">${journeySteps.map((s,i)=>`<li class="${i===stage?'current':i<stage?'done':''}" ${i===stage?'aria-current="step"':''}><b>${ico(i<stage?'check':['pin','building','floor','door','check'][i])}</b><span>${s[en?1:0]}</span></li>`).join('')}</ol><div class="route-instruction journey-stage" data-stage="${stage}"><div class="way-stage-heading"><small>0${stage+1} / 05</small><h3>${headings[stage]}</h3></div>${body}<details class="way-help"><summary>${ico('help')}${t('更多提示与演示说明','More help & demo scope')}</summary><p>${help}</p><p>${t('情境演示：假设定位与室内服务可用；入口、参照点和路线未经现场核验。','Scenario: assumes location and indoor services. Entrances, landmarks and routes are not field-verified.')}</p></details>${stage>0?button('previousClue','上一步','Previous','retry','text-button full'):''}</div><p class="way-demo-mark">${ico('help')}${t('演示 · 位置与路径为假设','DEMO · ASSUMED LOCATION & PATH')}</p></div>`;
}
